const ExcelJS = require('exceljs');
const fs = require('fs');

async function main() {
  const text = fs.readFileSync('/workspace/handbook_text.txt', 'utf-8').trim();
  const lines = text.split('\n').filter(line => line.trim() !== '');

  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Handbook Text');

  // Add header
  sheet.columns = [
    { header: 'Line #', key: 'line', width: 10 },
    { header: 'Extracted Text', key: 'text', width: 80 },
  ];

  // Style header row
  sheet.getRow(1).font = { bold: true };

  // Add each line of extracted text
  lines.forEach((line, i) => {
    sheet.addRow({ line: i + 1, text: line.trim() });
  });

  await workbook.xlsx.writeFile('/workspace/handbook_extracted.xlsx');
  console.log('Excel file created: /workspace/handbook_extracted.xlsx');
}

main().catch(console.error);

